#!/usr/bin/env node
/**
 * Writes wrangler.deploy.toml: wrangler.toml with its two account-specific placeholders filled in, so the
 * committed config never carries a real account or database ID.
 *
 *   <YOUR_CLOUDFLARE_ACCOUNT_ID>  ← CLOUDFLARE_ACCOUNT_ID   (32 hex characters)
 *   <YOUR_D1_DATABASE_ID>         ← D1_DATABASE_ID          (a UUID, from `npx wrangler d1 create achromat-mom-db`)
 *
 * The values come from the environment or from a local .env file (git ignores both .env and the generated file).
 * The generated file sits next to wrangler.toml, so every relative path in it (main, assets, migrations) still
 * resolves. Use it for every command that talks to your account:
 *
 *   npm run deploy                                        (runs this script, then wrangler deploy --config …)
 *   npx wrangler d1 migrations apply achromat-mom-db --remote --config wrangler.deploy.toml
 *   npx wrangler secret put <NAME> --config wrangler.deploy.toml
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const envFile = join(root, ".env");
if (existsSync(envFile)) process.loadEnvFile(envFile);

const VALUES = [
  { placeholder: "<YOUR_CLOUDFLARE_ACCOUNT_ID>", name: "CLOUDFLARE_ACCOUNT_ID", pattern: /^[0-9a-f]{32}$/ },
  { placeholder: "<YOUR_D1_DATABASE_ID>", name: "D1_DATABASE_ID", pattern: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/ },
];

let config = readFileSync(join(root, "wrangler.toml"), "utf8");
const problems = [];
for (const { placeholder, name, pattern } of VALUES) {
  const value = process.env[name]?.trim() ?? "";
  if (!pattern.test(value)) {
    problems.push(`${name} is ${value === "" ? "not set" : "malformed"}`);
    continue;
  }
  if (!config.includes(placeholder)) {
    problems.push(`wrangler.toml no longer contains ${placeholder}`);
    continue;
  }
  config = config.replaceAll(placeholder, value);
}
const leftover = config.match(/<YOUR_[A-Z0-9_]+>/g);
if (leftover) problems.push(`unfilled placeholders: ${[...new Set(leftover)].join(", ")}`);

if (problems.length > 0) {
  console.error(`deploy-config: ${problems.join("; ")}. Set them in the environment or in a local .env file.`);
  process.exit(1);
}

const header = "# GENERATED by scripts/deploy-config.mjs from wrangler.toml. Do not edit or commit; edit wrangler.toml.\n";
writeFileSync(join(root, "wrangler.deploy.toml"), header + config);
console.log("deploy-config: wrote wrangler.deploy.toml");
